LEGAL.badge=["Verified Business badge","<p style='font-size:1.2rem;color:var(--ink)'>New business, no reviews yet? Show visitors you’re real. A badge for your website, backed by a check of your business, for a one-time $25.</p><p><img src='/badge.svg' alt='Verified Business badge, checked by FollowThrough' width='260' height='72'></p><div class='cta'><a class='btn' href='/badge#order'>Order your badge</a></div><h3>Why it matters</h3><p>A new business has no reviews, no name people know and no track record. A first-time visitor can’t tell a real local business from someone who’ll take a deposit and disappear, so many leave without getting in touch. The badge gives them an independent reason to trust you, which can mean more calls, form fills and booked jobs.</p><h3>What the badge says</h3><p>There is one level for now: <b style='color:var(--ink)'>Verified Business</b>. Your identity, registration, website address and contact details have been confirmed.</p><h3>How the check works</h3>"+L(["<b>Your Google Business Profile is verified.</b> Google confirms a business is real before it marks its profile as verified, for example with a video call or a code sent to the business. This is the main check.","<b>Your business is registered.</b> I find it in your state’s business register or, for a sole owner, your city or county’s records.","<b>Your website is yours.</b> The website on your Google profile is the one the badge goes on.","<b>You’re reachable.</b> The phone number and email on your website match your Google profile, and you answer my email."])+"<p>Everything I check is public, so you don’t give me access to any account.</p><h3>What you get</h3>"+L(["The badge for your website, with a short code to paste in, or to forward to whoever runs your site","A profile in the <a href='/verified'>directory of verified businesses</a>, which your badge links to: one more listing for your business, with a link to your website","The date of the check on your profile, so visitors can see it’s current"])+"<h3>Price</h3><p style='color:var(--ink)'><b style='font-size:1.6rem'>$25</b> one time</p><p>I check first and email you the result, usually within 2 business days. If you pass, you get a secure payment link, and the badge arrives once you’ve paid. If you don’t pass, you pay nothing, and I tell you what was missing.</p><h3>What it isn’t</h3>"+L(["A review or a rating. It confirms you’re real and reachable, not how good your work is.","A promise of more customers or a higher place on Google.","For sale to businesses that don’t pass. The check is the same for everyone."])+"<h3>Questions people ask</h3>"+Q([["My Google profile isn’t verified yet. Can I still order?","Verify it first. It’s free in Google Business Profile, and Google walks you through it. You can order before then, but you won’t pass until it’s done. You pay only when you pass."],["Do I need a website?","Yes. The badge goes on your website, and the check confirms the website is yours."],["How do I put the badge on my website?","Paste the short code I email you where you’d like the badge, for example in your footer or next to your contact form. On Wix, Squarespace and WordPress, use a block called “Embed” or “Custom HTML”. Or forward my email to whoever runs your site."],["How long does it last?","As long as your business still passes. I may check again at any time. If your Google profile loses its verification or the business closes, I take your profile down. Details are in the <a href='/service-terms'>service terms</a>."],["Will it help me show up on Google?","It adds one more listing with a link to your website, which can help a little. It doesn’t promise a higher place. For your listings and Google profile, see <a href='/visibility'>Visibility Autopilot</a>."]])+"<h3 id='order'>Order your badge</h3><p>Send your details and I’ll check your business. Nothing to pay yet.</p><form id='bf' class='card'><div class='calc two' style='margin-top:0'><label>Business name<input id='bn' required maxlength='120' autocomplete='organization'></label><label>Your website<input id='bw' required maxlength='200' placeholder='yourbusiness.com' inputmode='url' autocomplete='url'></label><label>Link to your Google profile, if you have it<input id='bg' maxlength='500' placeholder='Copy it from Google Maps'></label><label>Your email<input type='email' id='be' required maxlength='254' autocomplete='email'></label></div><label style='display:flex;gap:8px;align-items:flex-start;font-size:.9rem'><input type='checkbox' id='bok' required> <span>I agree to the <a href='/service-terms'>service terms</a> and have read the <a href='/privacy'>privacy policy</a>.</span></label><button class='btn' type='submit' style='margin-top:14px'>Check my business</button><p id='bs' role='status'></p></form>"];
LEGAL.verified=["Verified businesses","<p>Every business here passed the <a href='/badge'>Verified Business</a> check: a verified Google Business Profile, a registration on record, and a website and contact details that match. The date shows when it was checked. The badge confirms a business is real and reachable. It isn’t a review of its work.</p>"+(VB.length?"<div class='cols'>"+VB.map(function(b){return "<div class='col' id='"+b.id+"'><h3>"+b.n+"</h3><p>"+b.trade+", "+b.at+"</p><p><a href='"+b.web+"' rel='noopener'>"+b.web.replace(/^https?:\/\/(www\.)?/,"").replace(/\/$/,"")+"</a></p><p>Verified Business, checked "+b.d+"</p></div>"}).join("")+"</div>":"<p>The first verified businesses will appear here soon.</p>")+"<h3>Run a service business?</h3><p>Get your own badge and a profile here for a one-time $25.</p><div class='cta'><a class='btn' href='/badge'>Get the Verified Business badge</a></div>"];
function extra(t){var f=FULL[t.s];if(!f)return "";return "<div class='legal'><h2 style='margin-top:44px'>"+t.n+" deep dive</h2><h3>Licensing and rules</h3>"+L(f.lic)+"<h3>Itemized start-up costs</h3><div class='xs'><table class='cost'>"+f.cost.map(function(r){return "<tr><td>"+r[0]+"</td><td>"+r[1]+"</td></tr>"}).join("")+"</table></div><p>"+f.costnote+"</p><h3>Your first 90 days</h3>"+f.plan.map(function(r){return "<p><b style='color:var(--ink)'>"+r[0]+":</b> "+r[1]+"</p>"}).join("")+"<h3>Pricing example</h3><p>"+f.price+"</p><h3>Mistakes to avoid</h3>"+L(f.mistakes)+"<h3>Objection library</h3>"+Q(f.obj)+"<h3>Questions people ask</h3>"+Q(f.faq)+"<h3>Tools to consider</h3>"+L(f.tools)+"</div>"}
var app=document.getElementById("app"),done=[];
function get(s){try{return JSON.parse(localStorage.getItem("ft:"+s)||"[]")}catch(e){return[]}}
function put(s,v){try{localStorage.setItem("ft:"+s,JSON.stringify(v))}catch(e){}}
function find(s){return T.filter(function(t){return t.s===s})[0]}
function an(n){return (/^[AEIOU]/.test(n)?"an ":"a ")+n}
// The signup form. On a guide page t is that trade; elsewhere the visitor picks their trade from a list.
function signup(t){return '<div class="signup" id="signup"><h2>Get the free '+(t?t.n+' ':'')+'playbook</h2><p>Scripts, tips and objection answers for your trade, as a two-page PDF. Enter your email and it’s in your inbox in a few minutes.</p><form id="f">'+(t?'':'<select id="tr" required aria-label="Your trade"><option value="">Which trade are you in?</option>'+CATS.map(function(c,i){return '<optgroup label="'+c+'">'+T.filter(function(x){return x.c===i}).map(function(x){return '<option value="'+x.s+'">'+x.n+'</option>'}).join("")+'</optgroup>'}).join("")+'</select>')+'<input type="email" id="em" required placeholder="you@example.com" aria-label="Your email"><button class="btn" type="submit">Send me the playbook</button></form><label><input type="checkbox" id="ok" form="f" required> <span>I agree to receive the playbook and tips by email, and have read the <a href="/privacy">privacy policy</a>.</span></label><p id="fs" role="status"></p></div>'}
function wireSignup(t){var f=document.getElementById("f");if(!f)return;f.onsubmit=function(e){e.preventDefault();var b=f.querySelector("button"),ok=document.getElementById("ok"),st=document.getElementById("fs"),tr=document.getElementById("tr"),name=t?t.n:tr.options[tr.selectedIndex].text;b.disabled=true;st.textContent="Sending…";fetch(FORM_URL,{method:"POST",headers:{"Content-Type":"application/json",Accept:"application/json"},body:JSON.stringify({email:document.getElementById("em").value,trade:t?t.s:tr.value,consent:ok.checked})}).then(function(r){if(!r.ok)throw r;f.style.display=ok.parentNode.style.display="none";st.textContent="Thanks! Your "+name+" playbook is on its way. It should be in your inbox in a few minutes; if not, check your spam folder."}).catch(function(){b.disabled=false;st.innerHTML="Sorry, that didn’t go through. Please try again, or email me at <a href='mailto:"+CONTACT+"'>"+CONTACT+"</a>."})}}
function wireBadge(){var f=document.getElementById("bf"),st=document.getElementById("bs"),v=function(id){return document.getElementById(id).value};f.onsubmit=function(e){e.preventDefault();var b=f.querySelector("button");b.disabled=true;st.textContent="Sending…";fetch(BADGE_URL,{method:"POST",headers:{"Content-Type":"application/json",Accept:"application/json"},body:JSON.stringify({business:v("bn"),website:v("bw"),google:v("bg"),email:v("be"),consent:document.getElementById("bok").checked})}).then(function(r){if(!r.ok)throw r;[].forEach.call(f.children,function(c){if(c!==st)c.style.display="none"});st.textContent="Thanks! I’ll check your business and email you the result, usually within 2 business days."}).catch(function(){b.disabled=false;st.innerHTML="Sorry, that didn’t go through. Please try again, or email me at <a href='mailto:"+CONTACT+"'>"+CONTACT+"</a>."})}}
function tiles(list){return '<div class="grid">'+list.map(function(t){return '<a class="tile" href="/'+t.s+'"><b>'+t.n+'</b></a>'}).join("")+'</div>'}
function calc(){return '<section><h1>Lost quotes calculator</h1><p class="lead">See what winning a few more of your quotes is worth. Most quotes go quiet, not “no,” so a short follow-up is often all it takes.</p><div class="calc"><label>Quotes you send a month<input type="number" id="cq" min="0" step="1" value="20" inputmode="numeric"></label><label>Jobs you win out of every 10 quotes<input type="number" id="cw" min="0" max="10" step="0.5" value="3" inputmode="decimal"></label><label>Average job price ($)<input type="number" id="cp" min="0" step="50" value="1500" inputmode="numeric"></label></div><div class="card" id="cr" aria-live="polite"></div><p style="font-size:.9rem;color:var(--muted);margin-top:12px">Simple math on your own numbers, not a promise of results.</p><h2>How to win more of them</h2><p>Follow up. A short, friendly message on day 2, day 5 and day 12 brings back many quotes that went quiet. The <a href="/sales">Sales hub</a> has the exact words, and each <a href="/guides">start-up guide</a> has answers to the objections your trade hears.</p></section>'+signup()}
function wireCalc(){var n=function(id){return Math.max(0,+document.getElementById(id).value||0)},usd=function(x){return "$"+Math.round(x).toLocaleString("en-US")},jobs=function(x){x=Math.round(x*10)/10;return x+(x===1?" job":" jobs")};
var up=function(){var q=n("cq"),w=Math.min(10,n("cw")),p=n("cp"),r='<p style="font-size:1.2rem;color:var(--ink)"><b>Right now:</b> about '+jobs(q*w/10)+' and '+usd(q*w/10*p)+' a month.</p>';
[1,2,3].forEach(function(k){if(w+k<=10)r+='<p class="a"><b>Win '+k+' more in 10:</b> +'+jobs(q*k/10)+', +'+usd(q*k/10*p)+' a month, +'+usd(q*k/10*p*12)+' a year.</p>'});
if(w>9)r+='<p class="a">You win nearly every quote. Nice work.</p>';document.getElementById("cr").innerHTML=r};
["cq","cw","cp"].forEach(function(id){document.getElementById(id).oninput=up});up()}
function home(){
var h='<section class="hero"><div><h1>Start the business. Then get the jobs.</h1><p class="lead">Free step-by-step start-up guides for service trades, plus sales scripts and objection answers, so you can turn quote requests into booked work.</p><div class="cta"><a class="btn" href="/guides">Browse start-up guides</a><a class="btn ghost" href="/#demo">See a sample objection</a></div></div><div class="thread" aria-label="Example text thread: a quote goes quiet, then a follow-up books the job"><div class="msg them">Hi, can you quote a roof repair? Leak over the garage.</div><div class="msg me">Sure. Total is $1,850, parts and labor.</div><div class="gap">6 days of silence</div><div class="msg me late" style="--i:0">Hi Mark, quick check-in. Is the garage leak still dripping? I have a Thursday slot if you want it fixed before the next rain.</div><div class="msg them late" style="--i:1">Yes! Thursday works. Sorry, got busy.</div></div></section>';
h+='<section><h2>What you’ll find here</h2><div class="cols"><div class="col"><h3>Start-up guides</h3><p>Costs, busy season and a checklist from LLC to first customers for fifteen trades.</p></div><div class="col"><h3>Objection handling</h3><p>Honest answers to “too expensive” and “I need to think about it.”</p></div><div class="col"><h3>Quote follow-up</h3><p>Most quotes go quiet, not “no.” Get messages that bring them back.</p></div></div></section>';
h+='<section id="demo"><h2>A sample objection handler</h2><p>Pick a trade.</p><div class="demo"><div class="tabs" id="tabs"></div><div class="card" aria-live="polite"><div class="q" id="q"></div><p class="a" id="a"></p></div></div></section>';
h+='<section><h2>How it plays out</h2><p>Examples of the scripts at work in everyday situations. The names and numbers are made up.</p><div class="cols ex">'+EX.map(function(e){return '<div class="col"><h3>'+e[0]+'</h3><p><b>What happened:</b> '+e[1]+'</p><div class="tpl">'+e[2]+'</div><p><b>Result:</b> '+e[3]+'</p></div>'}).join("")+'</div><p style="margin-top:22px">Has a script here helped you win a job? Email me at <a href="mailto:'+CONTACT+'">'+CONTACT+'</a>. With your OK, I’ll share your story here.</p></section>';
h+='<section><h2>What are quiet quotes costing you?</h2><p>Enter how many quotes you send, how many you win and your average job. See what winning a few more is worth each month.</p><a class="btn" href="/calculator">Try the calculator</a></section>';
h+='<section><h2>Get found, too</h2><p>Visibility Autopilot keeps your business listed correctly on the directories that matter for your trade, looks after your Google Business Profile and fixes what holds your website back. One monthly bill, results in plain numbers, cancel any time.</p><a class="btn" href="/visibility">See Visibility Autopilot</a></section>';
h+='<section><h2>New, with no reviews yet?</h2><p>The Verified Business badge shows visitors to your website that your business is real: your Google profile, registration, website and contact details, checked. A one-time $25, and you pay only if you pass.</p><a class="btn" href="/badge">See the Verified Business badge</a></section>';
h+='<section><h2>Start-up guides by trade</h2>'+CATS.map(function(c,i){return '<div class="cat"><h3>'+c+'</h3>'+tiles(T.filter(function(t){return t.c===i}))+'</div>'}).join("")+'</section><div id="home-contact">'+signup()+'</div>';
return h}
function guides(){return '<section><h1>Start-up guides</h1><p>Pick your trade for costs, busy season and a step-by-step checklist.</p>'+CATS.map(function(c,i){return '<div class="cat"><h3>'+c+'</h3>'+tiles(T.filter(function(t){return t.c===i}))+'</div>'}).join("")+'</section>'}
function guide(t){
done=get(t.s);
var h='<section><div class="crumbs"><a href="/guides">Guides</a> / '+CATS[t.c]+'</div><h1>How to start '+an(t.n)+' business</h1><div class="facts"><div class="fact"><h3>Start-up cost</h3><p>'+t.cost+'</p></div><div class="fact"><h3>Busy season</h3><p>'+t.season+'</p></div><div class="fact"><h3>Is it a good fit?</h3><p>'+t.fit+'</p></div><div class="fact"><h3>Where the money goes</h3><p>'+t.spend+'</p></div></div><p style="font-size:.9rem;color:var(--muted)">Costs are rough estimates. Rules vary by state. See the <a href="/disclaimer">disclaimer</a>.</p><div class="facts"><div class="offer"><h3>Get found by local customers</h3><p>Visibility Autopilot keeps your Google profile and 40+ directory listings right, and shows what holds your website back. Try it free for 30 days, then from $99 a month. Cancel any time.</p><a class="btn" href="/visibility">See Visibility Autopilot</a></div><div class="offer"><h3>New, with no reviews yet?</h3><p>The Verified Business badge shows visitors to your website that your business is real. A one-time $25, and you pay only if you pass.</p><a class="btn" href="/badge">Get the Verified badge</a></div></div><h2>Step by step</h2><div class="prog" id="prog"></div><div class="bar"><i id="bar"></i></div><div style="height:16px"></div>';
STEPS.forEach(function(s,i){h+='<div class="step" id="st'+i+'"><button class="chk" data-i="'+i+'" aria-label="Mark step '+(i+1)+' completed"></button><div><h3>Step '+(i+1)+': '+s[0]+'</h3><p style="margin-bottom:0">'+s[1]+'</p><p class="tip"><b>'+(i===6?'Tips and tricks: ':'What to look for: ')+'</b>'+t.tips[i]+'</p>'+(i===5?'<p style="margin:10px 0 0;font-size:.95rem;color:var(--muted)">No time for your Google profile and listings? <a href="/visibility">Visibility Autopilot</a> looks after them for you. New, with no reviews yet? The <a href="/badge">Verified Business badge</a> shows visitors you’re real.</p>':'')+'</div></div>'});
h+=extra(t)+'</section>'+signup(t)+'<section><h2>Related guides</h2><div class="rel">'+T.filter(function(x){return x.c===t.c&&x.s!==t.s}).map(function(x){return '<a class="btn ghost" target="_blank" rel="noopener" href="/'+x.s+'">'+x.n+' guide</a>'}).join("")+'<a class="btn ghost" target="_blank" rel="noopener" href="/guides">All guides</a></div></section>';
return h}
function wirePlan(){var f=document.getElementById("pf"),st=document.getElementById("ps"),v=function(id){return document.getElementById(id).value};app.querySelectorAll("[data-plan]").forEach(function(b){b.onclick=function(){document.getElementById("pp").value=b.dataset.plan;f.scrollIntoView();document.getElementById("pn").focus({preventScroll:true})}});f.onsubmit=function(e){e.preventDefault();var b=f.querySelector("button");b.disabled=true;st.textContent="Sending…";fetch(PLAN_URL,{method:"POST",headers:{"Content-Type":"application/json",Accept:"application/json"},body:JSON.stringify({plan:v("pp"),name:v("pn"),business:v("pb"),email:v("pe"),phone:v("ph"),message:v("pm"),consent:document.getElementById("pok").checked})}).then(function(r){if(!r.ok)throw r;[].forEach.call(f.children,function(c){if(c!==st)c.style.display="none"});st.textContent="Thanks! I’ll email you the next steps, usually within 2 business days."}).catch(function(){b.disabled=false;st.innerHTML="Sorry, that didn’t go through. Please try again, or email me at <a href='mailto:"+CONTACT+"'>"+CONTACT+"</a>."})}}
function paint(t){STEPS.forEach(function(s,i){var e=document.getElementById("st"+i),on=done.indexOf(i)>-1;e.className="step"+(on?" done":"");e.firstChild.textContent=on?"✓":"";e.firstChild.setAttribute("aria-pressed",on)});document.getElementById("prog").textContent=done.length+" of 7 steps completed";document.getElementById("bar").style.width=(done.length/7*100)+"%"}
function render(id){
var t=find(id),h;
if(LEGAL[id])h='<section class="legal"><h1>'+LEGAL[id][0]+'</h1>'+LEGAL[id][1]+'</section>';
else if(id==="guides")h=guides();else if(id==="calculator")h=calc();else if(t)h=guide(t);else{h=home();id="home"}
app.innerHTML=h;
if(t){paint(t);app.querySelectorAll(".chk").forEach(function(b){b.onclick=function(){var i=+b.dataset.i,k=done.indexOf(i);k>-1?done.splice(k,1):done.push(i);put(t.s,done);paint(t)}});wireSignup(t)}
else if(id==="calculator"){wireCalc();wireSignup()}
else if(id==="badge")wireBadge();
else if(id==="visibility")wirePlan();
else if(id==="home"){wireSignup();var tb=document.getElementById("tabs");var sh=function(i){[].forEach.call(tb.children,function(b,k){b.setAttribute("aria-selected",k===i)});document.getElementById("q").textContent=OBJ[i][1];document.getElementById("a").textContent=OBJ[i][2]};OBJ.forEach(function(o,i){var b=document.createElement("button");b.type="button";b.textContent=o[0];b.onclick=function(){sh(i)};tb.appendChild(b)});sh(0)}
document.title=t?t.n+" start-up guide | FollowThrough":LEGAL[id]?LEGAL[id][0]+" | FollowThrough":id==="guides"?"Start-up guides | FollowThrough":id==="calculator"?"Lost quotes calculator | FollowThrough":"FollowThrough: start and sell a service business";
document.querySelector('meta[name="description"]').content=t?"How to start "+an(t.n)+" business: start-up costs, licensing, a 90-day plan and sales scripts to win your first jobs.":id==="calculator"?"Free calculator for service businesses: see what winning a few more of your quotes is worth each month and year.":id==="visibility"?"Visibility Autopilot: directory listings, Google Business Profile care and website fixes for local service businesses, on one monthly bill.":id==="badge"?"Verified Business badge: show visitors your new service business is real. Your Google profile, registration, website and contact details checked, for a one-time $25.":id==="verified"?"Service businesses that passed the FollowThrough Verified Business check.":DESC}
