function go(u){var p=String(u||"").split("#"),id=p[0].split("/").pop(),h=p[1]||"",to={"home-contact":"signup",signup:"signup",demo:"demo"}[h];if(h==="moving-transportation")h="hauling-transportation";if(!page(id)){id=page(h)?h:"";if(id||h==="home")try{history.replaceState(null,"","/"+id)}catch(x){}}render(id);var s=document.getElementById(to||h);s?s.scrollIntoView():window.scrollTo(0,0)}
document.addEventListener("click",function(e){var a=e.target.closest&&e.target.closest('a[href^="/"]');if(a&&!a.target&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey){e.preventDefault();try{history.pushState(null,"",a.getAttribute("href"))}catch(x){}go(a.getAttribute("href"))}});
